/* Host-side unit test for the shim: includes prx.c directly so the static
 * helpers can be called. Usage: shim_unit ROOTDIR  (needs ROOTDIR/etc/{passwd,group}
 * as generated by tests/smoke.sh). Exit status is a bitmask of failed checks. */
#include "../src/prx.c"
extern int printf(const char*, ...);

int main(int argc, char**argv) {
    int bad = 0;
    if (argc < 2) return 255;
    memcpy(g_root, argv[1], strlen(argv[1])+1);
    g_rl = strlen(argv[1]);

    /* group with 300 members (was truncated at 32) in a >48 KiB /etc/group */
    if (gr_lookup_dyn("big", 0, 0) != 1) bad |= 1;
    else {
        int m = 0;
        while (s_gr.mem[m]) m++;
        if (m != 300 || strcmp(s_gr.mem[299], "user299")) bad |= 2;
    }
    if (gr_lookup_dyn("last", 0, 0) != 1 || s_gr.gid != 5001) bad |= 4;
    /* entry located past 48 KiB in /etc/passwd */
    if (pw_lookup_dyn(0, 1, 99999) != 1 || strcmp(s_pw.name, "lastuser")) bad |= 8;
    /* membership scan used for initgroups-style emulation */
    u32 out[NVG];
    if (cr_collect("user299", 100, out, NVG) != 2 || out[1] != 5000) bad |= 16;

    /* IPv6 literal parser */
    u8 a[16];
    if (!parse_v6("2001:db8::1", 11, a) || a[0] != 0x20 || a[1] != 0x01 || a[15] != 1) bad |= 32;
    if (!parse_v6("::ffff:1.2.3.4", 14, a) || a[10] != 0xff || a[12] != 1 || a[15] != 4) bad |= 64;
    if (!parse_v6("::", 2, a) || !parse_v6("1:2:3:4:5:6:7:8", 15, a)) bad |= 128;
    if (parse_v6("1::2::3", 7, a) || parse_v6("12345::", 7, a) || parse_v6("1:2:3:4:5:6:7", 13, a)
        || parse_v6("fe80::1%eth0", 12, a) || parse_v6(":1", 2, a)) bad |= 256;

    printf("%d\n", bad);
    return bad ? 1 : 0;
}
